"""Завантаження та валідація записів каталогу фільмів із CSV."""import csvfrom pathlib import Pathfrom .errors import DataErrorREQUIRED_FIELDS = {"title", "director", "year", "duration", "rating"}def _parse_int(row: dict[str, str | None], field: str, row_number: int) -> int:    """Перетворює текстове поле CSV на ціле число."""    raw = row.get(field)    if raw is None or not raw.strip():        raise DataError(f"Рядок {row_number}: відсутнє значення у полі '{field}'")    try:        return int(raw.strip())    except ValueError as error:        raise DataError(f"Рядок {row_number}: поле '{field}' має бути цілим числом") from errordef _parse_float(row: dict[str, str | None], field: str, row_number: int) -> float:    """Перетворює текстове поле CSV на дійсне число."""    raw = row.get(field)    if raw is None or not raw.strip():        raise DataError(f"Рядок {row_number}: відсутнє значення у полі '{field}'")    try:        return float(raw.strip())    except ValueError as error:        raise DataError(f"Рядок {row_number}: поле '{field}' має бути числом") from errordef load_records(path: Path) -> list[dict[str, object]]:    """Читає CSV-файл, перевіряє заголовок і перетворює рядки на типізовані записи."""    try:        with path.open("r", encoding="utf-8", newline="") as source:            reader = csv.DictReader(source)            if reader.fieldnames is None:                raise DataError("CSV-файл порожній або не містить заголовка")            fieldnames = [name.strip() for name in reader.fieldnames]            if set(fieldnames) != REQUIRED_FIELDS or len(fieldnames) != len(REQUIRED_FIELDS):                raise DataError(                    "Некоректний заголовок CSV. Очікуються поля: "                    + ", ".join(sorted(REQUIRED_FIELDS))                )            reader.fieldnames = fieldnames            records: list[dict[str, object]] = []            for row_number, row in enumerate(reader, start=2):                if None in row:                    raise DataError(f"Рядок {row_number}: зайві стовпці у CSV-рядку")                raw_title = row.get("title")                raw_director = row.get("director")                if raw_title is None or raw_director is None:                    raise DataError(f"Рядок {row_number}: відсутнє обов'язкове текстове поле")                title = raw_title.strip()                director = raw_director.strip()                if not title:                    raise DataError(f"Рядок {row_number}: поле 'title' не може бути порожнім")                if not director:                    raise DataError(f"Рядок {row_number}: поле 'director' не може бути порожнім")                year = _parse_int(row, "year", row_number)                duration = _parse_int(row, "duration", row_number)                rating = _parse_float(row, "rating", row_number)                if year < 1888 or year > 2100:                    raise DataError(f"Рядок {row_number}: поле 'year' має бути в межах 1888..2100")                if duration <= 0:                    raise DataError(f"Рядок {row_number}: поле 'duration' має бути додатним")                if rating < 0.0 or rating > 10.0:                    raise DataError(f"Рядок {row_number}: поле 'rating' має бути в межах 0.0..10.0")                records.append(                    {                        "title": title,                        "director": director,                        "year": year,                        "duration": duration,                        "rating": rating,                    }                )            return records    except OSError as error:        raise DataError(f"Не вдалося прочитати файл: {path}") from error